package com.dukaops.backend.sales;
import java.math.BigDecimal; import java.util.UUID; import com.dukaops.backend.product.Product; import com.dukaops.backend.tenant.Tenant; import jakarta.persistence.*;
@Entity @Table(name="sales_order_items") public class SalesOrderItem { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private SalesOrder order; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") private Product product; private BigDecimal quantity,unitPrice,lineTotal; protected SalesOrderItem(){} public SalesOrderItem(Tenant t,SalesOrder o,Product p,BigDecimal q,BigDecimal price){id=UUID.randomUUID();tenant=t;order=o;product=p;quantity=q;unitPrice=price;lineTotal=price.multiply(q);} public Product getProduct(){return product;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getLineTotal(){return lineTotal;} }
